on conflict(role_key) do update set permissions=excluded.permissions,updated_at=now();

-- Missing new capabilities inherit their canonical defaults. Existing choices win.
update public.role_templates t set permissions=m.permissions || t.permissions
from public.role_permission_matrix m where m.role_key=t.key;
update public.agency_roles a set permissions=m.permissions || a.permissions
from public.role_permission_matrix m where m.role_key=a.template_key;

-- The deliberate default flip described in the header (house_manager only).
update public.role_templates t
set permissions = t.permissions || '{"correctiveActions.manage":true}'::jsonb
where t.key = 'house_manager'
  and (t.permissions ->> 'correctiveActions.manage') is distinct from 'true';

update public.agency_roles a
set permissions = a.permissions || '{"correctiveActions.manage":true}'::jsonb
where a.template_key = 'house_manager'
  and (a.permissions ->> 'correctiveActions.manage') is distinct from 'true';

commit;
